function transform(
    packageId: number,
    name: string,
    type: string,
    element: string,
    folder: string,
    clientId: number,
    enabled: number,
    access: number,
    isProtected: number,
    locked: number,
    manifestCache: string,
    params: string,
    customData: string,
    ordering: number,
    state: number,
) {
    return {
        packageId,
        name,
        type,
        element,
        folder,
        clientId,
        enabled: Boolean(Number(enabled)),
        access,
        protected: Boolean(isProtected),
        locked: Boolean(locked),
        manifestCache,
        params: isEmpty(params) ? {} : JSON.parse(params),
        customData,
        ordering,
        state,
    };
}
